scripts.script:
for i,v in next, getgc() do 
    if typeof(v) == 'function' and islclosure(v) and not isourclosure(v) then 
        local source = debug.info(v, 's')
        if source:find('ReplicatedFirst.LocalScript') and getinfo(v).name:lower():find('detect') then 
            hookfunction(v, function()
                warn('AC func blocked')
                return coroutine.yield() 
            end) 
        end 
    end 
end 

hookfunction(game.Players.LocalPlayer.Kick, function()
    return task.wait(9e9)
end) 

old_xpcall = hookfunction(getrenv().xpcall, function(...)
    local args = {...}
    if not checkcaller() then 
        for i,v in next, args do 
            if typeof(v) == 'function' then 
                if not isfunctionhooked(v) then 
                    hookfunction(v, function()
                        return coroutine.yield() 
                    end) 
                end 
            end 
        end 
    end 
    return old_xpcall(unpack(args))
end)
